package ai.eva.android.probe;
import android.app.*;import android.os.*;import android.net.Uri;import java.io.*;import java.nio.file.*;import org.json.*;
public class WorkspaceCheck extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();int code=0;File source=null,target=null,imported=null,project=null;try{android.content.Context c=getTargetContext();String id="check-"+java.util.UUID.randomUUID();project=WorkspaceFiles.project(c,id);try{WorkspaceFiles.project(c,"../escape");throw new Exception("traversal accepted");}catch(IOException expected){}try{WorkspaceFiles.resolve(c,"../outside");throw new Exception("outside accepted");}catch(IOException expected){}source=File.createTempFile("eva-input-",".bin",c.getCacheDir());target=File.createTempFile("eva-output-",".bin",c.getCacheDir());byte[] bytes=new byte[]{0,1,2,-1,13,10};Files.write(source.toPath(),bytes);JSONObject attachment=WorkspaceFiles.importUri(c,Uri.fromFile(source),id);imported=WorkspaceFiles.resolve(c,attachment.getString("path").substring("/root/eva-workspace/".length()));WorkspaceFiles.export(c,imported,Uri.fromFile(target));if(!java.util.Arrays.equals(bytes,Files.readAllBytes(target.toPath())))throw new Exception("binary export mismatch");if(attachment.getLong("size")!=bytes.length)throw new Exception("size mismatch");out.putString("result","PASS: native project path boundary, URI stream import, binary export byte equality. Synthetic file URIs; system picker UI tested separately.");}catch(Exception e){code=1;out.putString("error",e.toString());}finally{if(source!=null)source.delete();if(target!=null)target.delete();if(imported!=null){imported.delete();imported.getParentFile().delete();imported.getParentFile().getParentFile().delete();}if(project!=null)project.delete();}finish(code,out);}
}
